describe('Complete Checkout Flow - Sauce Labs Backpack', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should complete checkout with valid user credentials and backpack item', () => {
    // Login with standard_user credentials
    cy.get('[data-testid="username"]').type('standard_user');
    cy.get('[data-testid="password"]').type('secret_sauce');
    cy.get('[data-testid="login-button"]').click();

    // Verify login was successful
    cy.get('[data-testid="primary-header"]').should('contain', 'Sauce Labs');

    // Navigate to the backpack item
    cy.get('[data-testid="add-to-cart-sauce-labs-backpack"]').click();
    cy.get('[data-testid="shopping-cart-link"]').click();

    // Verify cart is open
    cy.get('[data-testid="contents_wrapper"]').should('be.visible');

    // Fill in shipping details
    cy.get('[data-testid="firstName"]').type('Saif');
    cy.get('[data-testid="lastName"]').type('Afzal');
    cy.get('[data-testid="postalCode"]').type('201301');

    // Click continue to view order summary
    cy.get('[data-testid="continue"]').click();

    // Verify overview page is displayed
    cy.get('[data-testid="secondary-header"]').should('contain', 'Order Summary');
    cy.get('[data-testid="item-4-img-link"]').should('be.visible');

    // Verify item details are visible
    cy.get('[data-testid="inventory-item-sauce-labs-backpack-img"]').should('be.visible');
    cy.get('[data-testid="inventory-item-description"]').should('contain', 'Sauce Labs Backpack');

    // Click finish to complete checkout
    cy.get('[data-testid="finish"]').click();

    // Verify confirmation header is displayed
    cy.get('[data-testid="complete-header"]').should('be.visible');
    cy.get('[data-testid="complete-header"]').should('contain', 'Thank you for your order!');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Order confirmed');

    // Verify cart is closed
    cy.get('[data-testid="shopping-cart-link"]').should('not.exist');
  });

  it('should handle invalid login and show error message', () => {
    // Attempt to login with invalid credentials
    cy.get('[data-testid="username"]').type('invalid_user');
    cy.get('[data-testid="password"]').type('wrong_password');
    cy.get('[data-testid="login-button"]').click();

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid username or password');

    // Verify user is not logged in
    cy.get('[data-testid="primary-header"]').should('not.contain', 'Sauce Labs');

    // Verify login form is still visible
    cy.get('[data-testid="login-form"]').should('be.visible');
  });
});
